refentry.refsect1:
  &reftitle.description;

&style.procedural;

   intfalsenullgrapheme_strlen
   stringstring



   Obtém o comprimento de uma string em unidade de grafema (não em bytes ou caracteres).

&reftitle.parameters;




   string



     A string sendo medida. Deve ser em UTF-8 válido.

  &reftitle.examples;

   Exemplo de grapheme_strlen


<?php

$char_a_ring_nfd = "a\xCC\x8A";  // 'LATIN SMALL LETTER A WITH RING ABOVE' (U+00E5) NFD
$char_o_diaeresis_nfd = "o\xCC\x88"; // 'LATIN SMALL LETTER O WITH DIAERESIS' (U+00F6) NFD

print grapheme_strlen( 'abc' . $char_a_ring_nfd . $char_o_diaeresis_nfd . $char_a_ring_nfd);

?>



  &example.outputs;


6



   Tratamento de entrada UTF-8 inválida

    grapheme_strlen retorna &null; ou &false; em caso de
    falha, inclusive quando a entrada não é UTF-8 válida.
    Use intl_get_error_code e
    intl_error_name para obter os detalhes do erro do ICU.



<?php

$string = "\xFF"; // sequência de bytes UTF-8 inválida
$length = grapheme_strlen($string);

if (!is_int($length)) {
    $code = intl_get_error_code();
    printf("grapheme_strlen() failed: %s (%d)\n", intl_error_name($code), $code);
} else {
    echo $length, PHP_EOL;
}

?>


   &example.outputs;


grapheme_strlen() failed: U_INVALID_CHAR_FOUND (10)

&reftitle.seealso;
Unicode Text Segmentation: Grapheme Cluster Boundaries
